def f(v,digits=3):return '—' if v is None else f'{v:,.{digits}f}'.replace(',','X').replace('.',',').replace('X','.')
def esc(x):return html.escape(str(x))
def pct(a,b):return 100*(a-b)/a

def table(headers,rows,caption=''):
    return '<div class="tablewrap"><table>'+('<caption>'+caption+'</caption>' if caption else '')+'<thead><tr>'+''.join('<th scope="col">'+esc(c)+'</th>' for c in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'

def namespace_svg(s,prefix):
    ids=re.findall(r'\bid="([^"]+)"',s)
    for ident in ids:
        s=s.replace('id="'+ident+'"','id="'+prefix+ident+'"').replace('#'+ident+'"','#'+prefix+ident+'"').replace('#'+ident+')','#'+prefix+ident+')')
    return s

def svg_plot(fig,label):
    out=io.StringIO();fig.savefig(out,format='svg',bbox_inches='tight',metadata={'Date':None});plt.close(fig)
    s=out.getvalue();s=s[s.index('<svg'):]
    return namespace_svg(s.replace('<svg ','<svg role="img" aria-label="'+esc(label)+'" ',1),'plot_'+hashlib.sha256(label.encode()).hexdigest()[:7]+'_')

