def box(x,y,w,h,title,body,fill='#eaf4ef'):
    lines=body.split('|')
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="{fill}" stroke="#b6cbc5"/><text x="{x+16}" y="{y+30}" font-size="18" font-weight="700">{esc(title)}</text>'+''.join(f'<text x="{x+16}" y="{y+57+22*i}" font-size="14">{esc(v)}</text>' for i,v in enumerate(lines))
def arrow(x1,y1,x2,y2):return f'<path d="M{x1},{y1} L{x2},{y2}" stroke="#557878" stroke-width="2" fill="none" marker-end="url(#a)"/>'
def diagram(content,height,label):
    result=f'<div class="svgscroll" role="region" tabindex="0" aria-label="Diagrama desplazable"><svg class="diagram" viewBox="0 0 1100 {height}" role="img" aria-label="{esc(label)}" xmlns="http://www.w3.org/2000/svg" style="font-family:system-ui,sans-serif;fill:#18313a"><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0L8,4L0,8" fill="#557878"/></marker></defs>{content}</svg></div>'
    return namespace_svg(result,'diagram_'+hashlib.sha256(label.encode()).hexdigest()[:7]+'_')
